// Little's Law for a review queue: W (wait, hours) = L (PRs in queue) / lambda (throughput, PRs/hour)
function waitHours(L, lambdaPerHour) { return L / lambdaPerHour; }

// Regime A: big 900-LOC PRs. A reviewer needs a contiguous block; effective throughput ~0.5 PR/hour,
// and 6 PRs pile up because none fit the gaps in a calendar.
const bigWait = waitHours(6, 0.5);
// Regime B: small/stacked ~200-LOC PRs. Each fits a 5-min gap; throughput ~4 PR/hour,
// and only 2 sit in queue because they drain fast.
const smallWait = waitHours(2, 4);

console.log('Big-PR regime:   ' + bigWait.toFixed(1) + 'h wait');
console.log('Small-PR regime: ' + smallWait.toFixed(1) + 'h wait');
console.log('Latency cut:     ' + (bigWait / smallWait).toFixed(0) + 'x faster');

// Defect-detection yield decays with size: ~85% at 300 LOC, halving every +500 LOC of fatigue.
function yieldPct(loc) {
  const base = 0.85;
  const decayed = base * Math.pow(0.5, Math.max(0, loc - 300) / 500);
  return Math.round(decayed * 100);
}
console.log('Yield @200 LOC:  ' + yieldPct(200) + '%');
console.log('Yield @900 LOC:  ' + yieldPct(900) + '%');
console.log('Yield @1600 LOC: ' + yieldPct(1600) + '%');
